  "inlineSchema": "// MetaConnect — Meta automation + Systeme.io CRM integration\n// Handles FB/IG comment-to-DM flows and lead form syncing\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// App user with email/password credentials\nmodel User {\n  id            String    @id @default(cuid())\n  createdAt     DateTime  @default(now())\n  name          String?\n  email         String?   @unique\n  emailVerified DateTime?\n  image         String?\n  passwordHash  String?\n\n  accounts            Account[]\n  sessions            Session[]\n  passwordResetTokens PasswordResetToken[]\n  metaConnections     MetaConnection[]\n  systemeioConnection SystemeioConnection?\n  projects            Project[]\n\n  @@index([createdAt])\n}\n\n/// One-time token for password reset flow\nmodel PasswordResetToken {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\n/// A connected Facebook Page (with optional linked Instagram account)\nmodel MetaConnection {\n  id                String   @id @default(cuid())\n  userId            String\n  pageId            String\n  pageName          String\n  pageAccessToken   String   @db.Text\n  igAccountId       String?\n  igName            String?\n  webhookSubscribed Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  projects Project[]\n\n  @@unique([userId, pageId])\n  @@index([userId])\n}\n\n/// Systeme.io API key per user (one per user)\nmodel SystemeioConnection {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  apiKey    String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n/// A project ties a Meta page to an automation type\nmodel Project {\n  id               String   @id @default(cuid())\n  userId           String\n  metaConnectionId String\n  name             String\n  /// \"comment\" | \"lead_form\"\n  type             String\n  /// \"active\" | \"paused\"\n  status           String   @default(\"active\")\n  systemeioTag     String\n  // Comment project fields\n  keyword          String?\n  postId           String?\n  dmMessage        String?  @db.Text\n  responseMessage  String?  @db.Text\n  // Lead form project fields\n  formId           String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  user           User           @relation(fields: [userId], references: [id], onDelete: Cascade)\n  metaConnection MetaConnection @relation(fields: [metaConnectionId], references: [id], onDelete: Cascade)\n  leads          Lead[]\n  conversations  Conversation[]\n\n  @@index([userId])\n  @@index([metaConnectionId])\n}\n\n/// A collected lead (from either comment flow or lead form)\nmodel Lead {\n  id         String   @id @default(cuid())\n  projectId  String\n  name       String\n  email      String\n  metaUserId String?\n  /// \"comment\" | \"lead_form\"\n  source     String\n  createdAt  DateTime @default(now())\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n  @@index([projectId, createdAt])\n}\n\n/// Active DM conversation for comment-to-DM flow (awaiting name/email reply)\nmodel Conversation {\n  id        String   @id @default(cuid())\n  projectId String\n  /// Page-scoped ID (PSID) for Messenger or Instagram IGSID\n  psid      String\n  /// \"awaiting_name\" | \"awaiting_email\" | \"completed\" | \"failed\"\n  state     String   @default(\"awaiting_name\")\n  name      String?\n  email     String?\n  attempts  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, psid])\n  @@index([psid])\n}\n\n// ─── NextAuth / Auth.js models ───────────────────────────────────────────────\n\nmodel Account {\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@id([provider, providerAccountId])\n}\n\nmodel Session {\n  sessionToken String   @id\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n",
